messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
Here is a single, self-contained HTML file that fulfills all your requirements.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Three.js Racing Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const TRACK_LENGTH = 100;
    const START_LINE = 0;
    const FINISH_LINE = TRACK_LENGTH;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 20, 90);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 200);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(10, 20, 10);
    dirLight.castShadow = true;
    dirLight.shadow.camera.left = -20;
    dirLight.shadow.camera.right = 20;
    dirLight.shadow.camera.top = 20;
    dirLight.shadow.camera.bottom = -20;
    scene.add(dirLight);

    // --- Environment ---
    // Ground
    const groundGeo = new THREE.PlaneGeometry(200, 200);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Finish Line (Checkerboard pattern using simple geometry)
    const finishGeo = new THREE.PlaneGeometry(20, 2);
    const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const finishLine = new THREE.Mesh(finishGeo, finishMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.set(0, 0.05, FINISH_LINE);
    scene.add(finishLine);

    // --- Car Builder ---
    function createCar(colorHex) {
        const carGroup = new THREE.Group();

        // Body
        const bodyGeo = new THREE.BoxGeometry(2, 1, 4);
        const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.3 });
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.position.y = 0.75;
        body.castShadow = true;
        carGroup.add(body);

        // Cabin
        const cabinGeo = new THREE.BoxGeometry(1.8, 0.6, 2);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.y = 1.4;
        cabin.position.z = -0.5;
        cabin.castShadow = true;
        carGroup.add(cabin);

        // Wheels
        const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222 });

        const positions = [
            [-1.1, 0.4, 1.2], [1.1, 0.4, 1.2], // Front
            [-1.1, 0.4, -1.2], [1.1, 0.4, -1.2] // Back
        ];

        positions.forEach(pos => {
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.position.set(...pos);
            wheel.rotation.z = Math.PI / 2;
            wheel.castShadow = true;
            carGroup.add(wheel);
        });

        return carGroup;
    }

    // --- Cars ---
    const redCar = createCar(0xff0000);
    redCar.position.set(-1, 0, 0); // Left lane
    scene.add(redCar);

    const blueCar = createCar(0x0000ff);
    blueCar.position.set(1, 0, 0); // Right lane
    scene.add(blueCar);

    // --- Animation State ---
    let startTime = performance.now();
    let animationId;

    function resetRace() {
        startTime = performance.now();
    }

    // --- Main Loop ---
    function animate() {
        requestAnimationFrame(animate);

        const currentTime = performance.now();
        const elapsed = (currentTime - startTime) / 1000; // seconds

        // --- Logic ---
        // Blue car: Constant speed (leads initially)
        const blueSpeed = 12; 
        let blueZ = START_LINE + (elapsed * blueSpeed);

        // Red car: Starts slower, then accelerates aggressively
        // We use a sigmoid-like curve or piecewise logic to simulate "overtaking"
        // Phase 1: Blue leads. Phase 2: Red accelerates past.
        // To make it loop forever, we clamp positions based on time.

        // Let's use a fixed timeline for the loop:
        // 0s - 4s: Blue leads.
        // 4s - 7s: Red accelerates and overtakes.
        // 7s - 8.5s: Red wins.
        // 8.5s - 9s: Reset.

        const totalCycleTime = 9; // seconds per loop
        const cycleTime = elapsed % totalCycleTime;

        let redZ;
        let blueZ;

        if (cycleTime < 7) {
            // Standard racing phase
            // Blue stays ahead until 7s
            blueZ = START_LINE + (cycleTime * 10); // Blue moves at 10 units/sec

            // Red moves slightly slower initially, then speeds up
            // Simple formula: Red moves 0.9x speed, but gets a boost near end
            // To simulate overtaking, let's use a specific curve
            // Red: starts at 8 units/sec.
            redZ = START_LINE + (cycleTime * 8);

            // Apply a boost to Red at the end to overtake
            if (cycleTime > 5) {
                const extraBoost = (cycleTime - 5) * 8;
                redZ += extraBoost;
            }
        } else {
            // Post-finish phase (Resetting)
            // Keep cars at finish line for a moment, then snap back
            const remaining = totalCycleTime - cycleTime; // 0 to 3 seconds

            if (remaining > 0.5) {
                // Just finished
                redZ = FINISH_LINE;
                blueZ = FINISH_LINE - 5; // Blue is 5 meters behind
            } else {
                // Resetting
                const t = remaining / 0.5; // 1 to 0
                redZ = FINISH_LINE * t;
                blueZ = (FINISH_LINE - 5) * t;
            }
        }

        // Update Positions
        redCar.position.z = redZ;
        blueCar.position.z = blueZ;

        // --- Camera Follow ---
        // Camera follows the leading car (Red usually, or Blue if he's still ahead)
        const leaderZ = Math.max(redZ, blueZ);

        // Smooth camera movement
        const targetCamZ = leaderZ + 15; // Look ahead
        const targetCamX = 15; // Side angle
        const targetCamY = 8; // High angle

        // Lerp for smoothness
        camera.position.x += (targetCamX - camera.position.x) * 0.05;
        camera.position.y += (targetCamY - camera.position.y) * 0.05;
        camera.position.z += (targetCamZ - camera.position.z) * 0.05;

        camera.lookAt(leaderZ, 0, 0);

        renderer.render(scene, camera);
    }

    // --- Window Resize ---
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // --- Start ---
    animate();

</script>
</body>
</html>
```
